window.AUTH=window.AUTH||{};window.AUTH["17-312"]={"d":"17-312","id":"2017/17-312","n":"United States v. Sanchez-Gomez","briefs":[{"k":"petitioner","label":"Brief of petitioner United States","date":"2018-01-22","url":"https://www.supremecourt.gov/DocketPDF/17/17-312/28798/20180122182804051_17-312%20Sanchez-Gomez.8.pdf","side":"pet","n":67},{"k":"respondent","label":"Brief of respondents Moises Patricio-Guzman, et al.","date":"2018-02-21","url":"https://www.supremecourt.gov/DocketPDF/17/17-312/36154/20180221165432571_Merits%20brief-Sanchez-Gomez%20Brief-Appendix.pdf","side":"res","n":64},{"k":"reply","label":"Reply of petitioner United States","date":"2018-03-14","url":"https://www.supremecourt.gov/DocketPDF/17/17-312/38876/20180314113714870_17-312rbUnitedStates.pdf","side":"pet","n":37}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Abney v. United States","cite":"431 U.S. 651","y":1977,"id":"1976/75-6521","sc":1,"by":{"0":"20, 22","1":"20, 25, 36, 38, 39","2":"8, 9, 10"},"q":[{"src":"brief","b":1,"text":"Cohen’s collateral-order exception is equally applicable in both civil and criminal proceedings.","cite":"431 U.S. 651, 659 n.4"},{"src":"brief","b":1,"text":"the personal strain, public embarrassment, and expense of a [second] criminal trial.","cite":"431 U.S. at 661"}]},{"t":"case","label":"Bell v. Wolfish","cite":"441 U.S. 520","y":1979,"id":"1978/77-1829","sc":1,"by":{"0":"25, 29","1":"16","2":"8"},"q":[{"src":"brief","b":1,"text":"a tradition dating from time out of mind that defendants will appear in court prior to their conviction as free men with their heads held high.","cite":"441 U.S. 520"}]},{"t":"case","label":"(III) Cases—Continued: Berman v. United States","cite":"302 U.S. 211","y":1937,"id":"scdb/1937-024","sc":1,"by":{"0":"19"},"q":[{"src":"brief","b":0,"text":"final determination of the merits of [his or her] criminal charge[s].","cite":"302 U.S. 211, 212"}]},{"t":"case","label":"Board of Sch. Comm’rs v. Jacobs","cite":"420 U.S. 128","y":1975,"id":"1974/73-1347","sc":1,"by":{"0":"37, 38"},"q":[{"src":"brief","b":0,"text":"the litigation is likely to become moot as to the initially named [challengers] prior to the exhaustion of appellate review.","cite":"420 U.S. 128, 130"}]},{"t":"case","label":"Campbell-Ewald Co. v. Gomez","cite":"136 S. Ct. 663","y":2016,"id":"2015/14-857","sc":1,"by":{"0":"31","2":"17"},"q":[{"src":"brief","b":0,"text":"personal stake in the outcome of the lawsuit, at any point during litigation, the action can no longer proceed and must be dismissed as moot.","cite":"136 S. Ct. 663, 669"}]},{"t":"case","label":"Cheney v. United States Dist. Court","cite":"542 U.S. 367","y":2004,"id":"2003/03-475","sc":1,"by":{"0":"14, 15, 27, 28, 29, 30","1":"passim","2":"11, 12, 15"},"q":[{"src":"brief","b":0,"text":"right to issuance of the writ is clear and indisputable,","cite":"542 U.S. at 381"},{"src":"brief","b":0,"text":"exceptional circumstances amounting to a judicial usurpation of power, or a clear abuse of discretion,","cite":"542 U.S. at 380"},{"src":"brief","b":1,"text":"These hurdles, however demanding, are not insuperable.","cite":"542 U.S. at 381"},{"src":"brief","b":1,"text":"used as a substitute for the regular appeals process.","cite":"542 U.S. at 380"},{"src":"brief","b":2,"text":"right to issuance of the writ is clear and indisputable.","cite":"542 U.S. at 381"},{"src":"brief","b":2,"text":"exceptional circumstances amounting to a judicial usurpation of power, or a clear abuse of discretion","cite":"542 U.S. at 380"},{"src":"argument","who":"Mr. Cahn","text":"But another species of mandamus is that that the Court authorized in Schlangenhauf and in Mallard and, indeed, I'd say even in Cheney, where there's a fundamental unresolved question about the authority of the district court."}]},{"t":"case","label":"City of Los Angeles v. Lyons","cite":"461 U.S. 95","y":1983,"id":"1982/81-1064","sc":1,"by":{"0":"40"}},{"t":"case","label":"Cobbledick v. United States","cite":"309 U.S. 323","y":1940,"id":"scdb/1939-076","sc":1,"by":{"0":"18","2":"7, 10"},"q":[{"src":"brief","b":0,"text":"[f ]inality as a condition of review is an historic characteristic of federal appellate procedure.","cite":"309 U.S. 323, 324"},{"src":"brief","b":0,"text":"[t]he correctness of a trial court’s rejection even of a constitutional claim made by the accused in the process of prosecution must await his conviction before its reconsideration by an appellate tribunal.","cite":"309 U.S. at 325"},{"src":"brief","b":2,"text":"[b]earing the discomfiture and cost of a prosecution for crime even by an innocent person is one of the painful obligations of citizenship.","cite":"309 U.S. at 325"}]},{"t":"case","label":"Cohen v. Beneficial Indus. Loan Corp.","cite":"337 U.S. 541","y":1949,"id":"scdb/1948-101","sc":1,"by":{"0":"19","1":"20, 32, 36, 38"},"q":[{"src":"argument","who":"Mr. Cahn","text":"Now collateral order review under Cohen exists because the decisions here conclusively determine an important question that was entirely separate from the merits, having nothing to do with the guilt or innocence of these particular Respondents."}]},{"t":"case","label":"Coopers & Lybrand v. Livesay","cite":"437 U.S. 463","y":1978,"id":"1977/76-1836","sc":1,"by":{"0":"20, 21","1":"20","2":"3, 7"},"q":[{"src":"brief","b":0,"text":"the order must conclusively determine the disputed question, resolve an important issue completely separate from the merits of the action, and be effectively unreviewable on appeal from a final judgment.","cite":"437 U.S. 463, 468"},{"src":"brief","b":0,"text":"effectively unreviewable on appeal from a final judgment.","cite":"437 U.S. at 468"},{"src":"brief","b":2,"text":"effectively unreviewable on appeal from a final judgment.","cite":"437 U.S. 463, 468"},{"src":"brief","b":2,"text":"effectively unreviewable on appeal from a final judgment,","cite":"437 U.S. at 468"}]},{"t":"case","label":"County of Riverside v. McLaughlin","cite":"500 U.S. 44","y":1991,"id":"1990/89-1817","sc":1,"by":{"0":"24, 29, 35, 38"},"q":[{"src":"brief","b":0,"text":"so inherently transitory that the trial court will not have even enough time to rule on a motion for class certification before the proposed representative’s individual interest expires.","cite":"500 U.S. at 52"}]},{"t":"case","label":"De Abadia-Peixoto v. United States Dep’t of Homeland Sec.","cite":"277 F.R.D. 572","y":2011,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.R.D./277/572/","by":{"0":"25"}},{"t":"case","label":"Deck v. Missouri","cite":"544 U.S. 622","y":2005,"id":"2004/04-5293","sc":1,"by":{"0":"11, 21, 28, 29","1":"passim","2":"3, 4, 13"},"q":[{"src":"brief","b":0,"text":"‘Blackstone and other English authorities recognized that the rule [disfavoring restraints] did not apply at the time of arraignment, or like proceedings before the judge.’","cite":"544 U.S. at 626"},{"src":"brief","b":0,"text":"did not apply at ‘the time of arraignment,’ or like proceedings before the judge.","cite":"544 U.S. at 626"},{"src":"brief","b":1,"text":"‘The courtroom’s formal dignity, which includes the respectful treatment of defendants, reflects the importance of the matter at issue, guilt or innocence, and the gravity with which Americans consider any deprivation of an individual’s liberty through criminal punishment.’","cite":"544 U.S. at 631"},{"src":"brief","b":1,"text":"‘affect the behavior of a general public whose demands for justice our courts seek to serve.’","cite":"544 U.S. at 631"},{"src":"brief","b":2,"text":"did not apply at ‘the time of arraignment,’ or like proceedings before the judge.","cite":"544 U.S. at 626"},{"src":"argument","who":"Mr. Kedem","text":"We don't think that that applies here, most notably because Respondents' due process claims could be reviewed following final judgment, which is one of the preconditions for application of the collateral-order doctrine. In Deck versus Missouri -"},{"src":"argument","who":"Mr. Kedem","text":"First of all, going to the nature of the right, the right that Respondents have invoked -- and I understand that they've changed their argument a little bit -- but throughout this litigation, they have invoked the right under -- under Deck versus Missouri, which is a right that's grounded in the fairness and accuracy of the underlying proceedings."},{"src":"argument","who":"Mr. Kedem","text":"Again, I understand that they've changed a little bit what they're conceiving of the right as, but the right that they've invoked under Deck versus Missouri is a right about accuracy and fairness, and that's very different from the bail right."}]},{"t":"case","label":"DeFunis v. Odegaard","cite":"416 U.S. 312","y":1974,"id":"1973/73-235","sc":1,"by":{"0":"32"},"q":[{"src":"brief","b":0,"text":"federal courts are without power to decide questions that cannot affect the rights of litigants in the case before them,","cite":"416 U.S. 312, 316"}]},{"t":"case","label":"Estelle v. Williams","cite":"425 U.S. 501","y":1976,"id":"1975/74-676","sc":1,"by":{"0":"28","2":"3"}},{"t":"case","label":"Flanagan v. United States","cite":"465 U.S. 259","y":1984,"id":"1983/82-374","sc":1,"by":{"0":"passim","1":"37","2":"3, 4, 6"},"q":[{"src":"brief","b":0,"text":"prohibits appellate review until conviction and imposition of sentence.","cite":"465 U.S. at 263"},{"src":"brief","b":0,"text":"interpreted the requirements of the collateral-order exception to the final judgment rule with the utmost strictness in criminal cases.","cite":"465 U.S. at 264"},{"src":"brief","b":2,"text":"validity cannot be adequately reviewed until trial is complete,","cite":"465 U.S. 259, 268"},{"src":"brief","b":2,"text":"expand[ ] the small class of criminal case orders covered by the collateral-order exception.","cite":"465 U.S. at 269"}]},{"t":"case","label":"Florence v. Board of Chosen Freeholders","cite":"566 U.S. 318","y":2012,"id":"2011/10-945","sc":1,"by":{"0":"25, 29","2":"8"}},{"t":"case","label":"General Tel. Co. v. Falcon","cite":"457 U.S. 147","y":1982,"id":"1981/81-574","sc":1,"by":{"0":"37"},"q":[{"src":"brief","b":0,"text":"The class-action device was designed as an exception to the usual rule that litigation is conducted by and on behalf of the individual named parties only.","cite":"457 U.S. 147, 155"}]},{"t":"case","label":"Genesis Healthcare Corp. v. Symczyk","cite":"569 U.S. 66","y":2013,"id":"2012/11-1059","sc":1,"by":{"0":"35, 36"},"q":[{"src":"brief","b":0,"text":"the fact that a putative class acquires an independent legal status once it is certified under Rule 23.","cite":"569 U.S. at 75"}]},{"t":"case","label":"Gerstein v. Pugh","cite":"420 U.S. 103","y":1975,"id":"1973/73-477","sc":1,"by":{"0":"passim","1":"12, 58"},"q":[{"src":"brief","b":1,"text":"individual could nonetheless suffer repeated deprivations.","cite":"420 U.S. at 111 n.11"},{"src":"argument","who":"Mr. Cahn","text":"Well, let me note that in Gerstein in Footnote 11, this Court said that pretrial detention is necessarily brief, speaking to the individual named plaintiffs, so that no one individual would have an opportunity to fully litigate their claim."},{"src":"argument","who":"Mr. Cahn","text":"And, in fact, the language in Gerstein is directly to the contrary of the rule, the new rule that the government is suggesting this Court adopt."},{"src":"argument","who":"Mr. Kedem","text":"Starting first with the question of mootness, my friend several times brought up Gerstein as an application of the exception for cases capable of repetition yet evading review."}]},{"t":"case","label":"Gunn v. Minton","cite":"568 U.S. 251","y":2013,"id":"2012/11-1118","sc":1,"by":{"0":"16"},"q":[{"src":"brief","b":0,"text":"‘Federal courts are courts of limited jurisdiction,’ possessing ‘only that power authorized by Constitution and statute.’","cite":"568 U.S. 251, 256"}]},{"t":"case","label":"Helstoski v. Meanor","cite":"442 U.S. 500","y":1979,"id":"1978/78-546","sc":1,"by":{"0":"20, 22","1":"20, 25","2":"8, 9"}},{"t":"case","label":"Honig v. Doe","cite":"484 U.S. 305","y":1988,"id":"1987/86-728","sc":1,"by":{"0":"42","1":"49, 53, 54, 56","2":"19, 20, 21"},"q":[{"src":"brief","b":0,"text":"reveal that, for purposes of assessing the likelihood that state authorities will reinflict a given injury, [the Court] generally ha[s] been unwilling to assume that the party seeking relief will repeat the type of misconduct that would once again place him or her at risk of that injury.","cite":"484 U.S. 305, 320"},{"src":"brief","b":1,"text":"whether, in the face of [a] statutory proscription, state or local school authorities may nevertheless unilaterally exclude disabled children from the classroom for dangerous or disruptive conduct growing out of their disabilities.","cite":"484 U.S. at 308"},{"src":"argument","who":"Mr. Cahn","text":"Smith in Honig versus Doe and -- and -- and Mr. Turner in the -- in the Turner versus Rogers were unable to avoid coming back in -- into that situation."}]},{"t":"case","label":"Kingdomware Techs., Inc. v. United States","cite":"136 S. Ct. 1969","y":2016,"id":"2015/14-916","sc":1,"by":{"0":"41, 43","1":"55, 56"}},{"t":"case","label":"Kokkonen v. Guardian Life Ins. Co. of Am.","cite":"511 U.S. 375","y":1994,"id":"1993/93-263","sc":1,"by":{"0":"16"}},{"t":"case","label":"Kremens v. Bartley","cite":"431 U.S. 119","y":1977,"id":"1976/75-1064","sc":1,"by":{"0":"37"},"q":[{"src":"brief","b":0,"text":"it is only a ‘properly certified’ class that may succeed to the adversary position of a named representative whose claim becomes moot.","cite":"431 U.S. 119, 132-133"}]},{"t":"case","label":"Lane v. Williams","cite":"455 U.S. 624","y":1982,"id":"1981/80-1240","sc":1,"by":{"0":"42","1":"57","2":"18, 19"},"q":[{"src":"argument","who":"Mr. Kedem","text":"That's correct, but it was true in cases such as Lane. I think it may have also been true in Spencer versus Kemna."},{"src":"argument","who":"Mr. Kedem","text":"This Court has never relied on those sorts of predictions and in cases like O'Shea, Lane, and Spencer, has explicitly said that a prediction of that sort is not permissible."}]},{"t":"case","label":"Lewis v. Continental Bank Corp.","cite":"494 U.S. 472","y":1990,"id":"1989/87-1955","sc":1,"by":{"0":"31","2":"17"},"q":[{"src":"brief","b":0,"text":"subsists through all stages of federal judicial proceedings, trial and appellate.","cite":"494 U.S. 472, 477"},{"src":"brief","b":2,"text":"subsists through all stages of federal judicial proceedings, trial and appellate,","cite":"494 U.S. 472, 477"}]},{"t":"case","label":"Midland Asphalt Corp. v. United States","cite":"489 U.S. 794","y":1989,"id":"1988/87-1905","sc":1,"by":{"0":"19, 20, 21, 22","2":"5"},"q":[{"src":"brief","b":0,"text":"carve[s] out a narrow exception to the normal application of the final judgment rule.","cite":"489 U.S. 794, 798"},{"src":"brief","b":0,"text":"an explicit statutory or constitutional guarantee that trial will not occur,","cite":"489 U.S. at 801"},{"src":"brief","b":2,"text":"narrow exception to the normal application of the final judgment rule.","cite":"489 U.S. 794, 798"}]},{"t":"case","label":"Mohawk Indus., Inc. v. Carpenter","cite":"558 U.S. 100","y":2009,"id":"2009/08-678","sc":1,"by":{"0":"24, 26","1":"passim"},"q":[{"src":"brief","b":0,"text":"can be adequately vindicated by other means.","cite":"558 U.S. 100, 107"},{"src":"brief","b":1,"text":"‘some particular value of a high order.’","cite":"558 U.S. 100, 107"},{"src":"brief","b":1,"text":"would imperil a substantial public interest or some particular value of a high order.","cite":"558 U.S. at 107"}]},{"t":"case","label":"Murphy v. Hunt","cite":"455 U.S. 478","y":1982,"id":"1981/80-2165","sc":1,"by":{"0":"40"},"q":[{"src":"brief","b":0,"text":"in the absence of a class action, the ‘capable of repetition, yet evading review’ doctrine [i]s limited to the situation where two elements [are] combined: (1) the challenged action [i]s in its duration too short to be fully litigated prior to its cessation or expiration, and (2) there [i]s a reasonable expectation that the same complaining party would be subjected to the same action again.","cite":"455 U.S. 478, 482"}]},{"t":"case","label":"O’Shea v. Littleton","cite":"414 U.S. 488","y":1973,"id":"1973/72-953","sc":1,"by":{"0":"41, 42","1":"56","2":"18"}},{"t":"case","label":"Parr v. United States","cite":"351 U.S. 513","y":1956,"id":"1955/320","sc":1,"by":{"0":"30","2":"14"},"q":[{"src":"brief","b":2,"text":"the most that could be claimed is that the district courts have erred in ruling on matters within their jurisdiction.","cite":"351 U.S. 513, 520"}]},{"t":"case","label":"Pasadena City Bd. of Educ. v. Spangler","cite":"427 U.S. 424","y":1976,"id":"1975/75-164","sc":1,"by":{"0":"38, 39","1":"58"}},{"t":"case","label":"Press-Enter. Co. v. Superior Court","cite":"478 U.S. 1","y":1986,"id":"1985/84-1560","sc":1,"by":{"0":"41, 43","1":"55, 56"}},{"t":"case","label":"Roche v. Evaporated Milk Ass’n","cite":"319 U.S. 21","y":1943,"id":"scdb/1942-071","sc":1,"by":{"0":"30"},"q":[{"src":"brief","b":0,"text":"has done no more than substitute mandamus for an appeal contrary to the statutes and the policy of Congress, which has restricted that court’s appellate review to final judgments of the district court.","cite":"319 U.S. 21, 32"}]},{"t":"case","label":"Roe v. Wade","cite":"410 U.S. 113","y":1973,"id":"1971/70-18","sc":1,"by":{"0":"41, 43","1":"55, 56"}},{"t":"case","label":"Schall v. Martin","cite":"467 U.S. 253","y":1984,"id":"1983/82-1248","sc":1,"by":{"0":"38"}},{"t":"case","label":"Sell v. United States","cite":"539 U.S. 166","y":2003,"id":"2002/02-5664","sc":1,"by":{"0":"22","1":"20, 22, 23, 25, 32, 36","2":"8, 10"},"q":[{"src":"brief","b":1,"text":"the very harm that [they] seek[] to avoid,","cite":"539 U.S. at 176"},{"src":"brief","b":1,"text":"raises questions of clear constitutional importance,","cite":"539 U.S. at 176"},{"src":"argument","who":"Mr. Kedem","text":"And, it -- it's also distinct from claims like this Court has recognized in Sell versus United States, where the severity of the physical interest was completely different."},{"src":"argument","who":"Mr. Cahn","text":"And I note that this Court has never said that the availability of some right -- or some forum to pursue litigation outside of the instant proceeding was relevant to collateral-order jurisdiction or to mandamus, and I'd point to both Stack and Sell as being contrary to that."},{"src":"argument","who":"Mr. Cahn","text":"But in Stack and Sell -- in Stack, this Court specifically said that the bringing of a separate habeas action in that case was improper. In Sell, Justice Scalia in his dissent suggested that the forced medication order could have been challenged in another proceeding, an Administrative Procedure Act challenge, to the order of the Bureau of Prisons to medicate the individual there."}]},{"t":"case","label":"Smith v. Bayer Corp.","cite":"564 U.S. 299","y":2011,"id":"2010/09-1205","sc":1,"by":{"0":"37"}},{"t":"case","label":"Sosna v. Iowa","cite":"419 U.S. 393","y":1975,"id":"1974/73-762","sc":1,"by":{"0":"15, 33, 34, 35, 37, 38"},"q":[{"src":"brief","b":0,"text":"factor [that] significantly affects the mootness determination.","cite":"419 U.S. at 399"},{"src":"brief","b":0,"text":"become[ ] moot as to them before the district court can reasonably be expected to rule on a certification motion.","cite":"419 U.S. at 402 n.11"}]},{"t":"case","label":"Spencer v. Kemna","cite":"523 U.S. 1","y":1998,"id":"1997/96-7171","sc":1,"by":{"0":"43","1":"57, 58","2":"18, 19"},"q":[{"src":"brief","b":0,"text":"cannot affect a subsequent parole determination unless [the prisoners] again violate state law, are returned to prison, and become eligible for parole. [The prisoners] themselves are able—and indeed required by law—to prevent such a possibility from occurring.","cite":"523 U.S. 1"},{"src":"brief","b":1,"text":"Respondents are now acutely aware of the fact that a criminal sentence in Illinois will include a special parole term.","cite":"523 U.S. 1"},{"src":"brief","b":2,"text":"contingent upon [litigants’] violating the law, getting caught, and being convicted.","cite":"523 U.S. 1, 15"},{"src":"brief","b":2,"text":"demonstrated a reasonable likelihood that he will once again be paroled and have that parole revoked.","cite":"523 U.S. at 17"},{"src":"argument","who":"Mr. Kedem","text":"That's correct, but it was true in cases such as Lane. I think it may have also been true in Spencer versus Kemna."},{"src":"argument","who":"Mr. Kedem","text":"This Court has never relied on those sorts of predictions and in cases like O'Shea, Lane, and Spencer, has explicitly said that a prediction of that sort is not permissible."}]},{"t":"case","label":"Stack v. Boyle","cite":"342 U.S. 1","y":1951,"id":"scdb/1951-001","sc":1,"by":{"0":"20, 22","1":"20, 23, 25, 35, 38","2":"8, 9, 11"},"q":[{"src":"brief","b":1,"text":"done in haste . . . without that full inquiry and consideration which the matter deserves.","cite":"342 U.S. at 11"},{"src":"argument","who":"Mr. Kedem","text":"And I think it's very hard to imagine a case like Stack about bail claims coming out the same way if every time someone wanted to challenge bail, a denial of bail on appeal, you had to pause the underlying criminal proceedings."},{"src":"argument","who":"Mr. Kedem","text":"-- in Stack can be immediately appealed."},{"src":"argument","who":"Mr. Cahn","text":"And I note that this Court has never said that the availability of some right -- or some forum to pursue litigation outside of the instant proceeding was relevant to collateral-order jurisdiction or to mandamus, and I'd point to both Stack and Sell as being contrary to that."}]},{"t":"case","label":"Swisher v. Brady","cite":"438 U.S. 204","y":1978,"id":"1977/77-653","sc":1,"by":{"0":"35, 38"}},{"t":"case","label":"Turner v. Rogers","cite":"564 U.S. 431","y":2011,"id":"2010/10-10","sc":1,"by":{"0":"41, 43","1":"49, 53, 55-56, 56","2":"19, 20, 21"},"q":[{"src":"brief","b":1,"text":"falls within a special category of disputes that are ‘capable of repetition’ while ‘evading review.’","cite":"564 U.S. 431, 439"},{"src":"brief","b":1,"text":"too short to be fully litigated.","cite":"564 U.S. at 439"}]},{"t":"case","label":"United States Parole Comm’n v. Geraghty","cite":"445 U.S. 388","y":1980,"id":"1979/78-572","sc":1,"by":{"0":"36, 38","1":"58, 59"},"q":[{"src":"brief","b":1,"text":"requires reference to the purposes of the case-or-controversy requirement.","cite":"445 U.S. 388, 402"}]},{"t":"case","label":"United States v. Hollywood Motor Car Co.","cite":"458 U.S. 263","y":1982,"id":"1981/81-1144","sc":1,"by":{"0":"17, 18, 21, 26","2":"6, 10, 11"},"q":[{"src":"brief","b":0,"text":"is inimical to piecemeal appellate review of trial court decisions which do not terminate the litigation.","cite":"458 U.S. 263, 265"},{"src":"brief","b":0,"text":"the policy against piecemeal appeals in criminal cases would be swallowed by ever-multiplying exceptions.","cite":"458 U.S. at 270"}]},{"t":"case","label":"United States v. Howard","cite":"480 F.3d 1005","y":2007,"url":"https://www.courtlistener.com/c/F.3d/480/1005/","by":{"0":"3, 8, 9, 29","2":"12, 13"},"q":[{"src":"brief","b":0,"text":"the exception to the mootness doctrine for cases that are ‘capable of repetition, yet evading review.’","cite":"480 F.3d at 1009"}]},{"t":"case","label":"United States v. MacDonald","cite":"435 U.S. 850","y":1978,"id":"1977/75-1892","sc":1,"by":{"0":"21, 23, 25, 26","2":"6, 10"},"q":[{"src":"brief","b":0,"text":"best considered only after the relevant facts have been developed.","cite":"435 U.S. at 858"},{"src":"brief","b":0,"text":"nothing about the circumstances * * * inherently limits the availability of the claim.","cite":"435 U.S. at 862"},{"src":"brief","b":2,"text":"to minimize anxiety and concern of the accused.","cite":"435 U.S. 850, 858"}]},{"t":"case","label":"United States v. Zuber","cite":"118 F.3d 101","y":1997,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/118/101/","by":{"0":"3","1":"13, 21, 41"},"q":[{"src":"brief","b":1,"text":"to be treated with respect and dignity in a public courtroom, not like a bear on a chain,","cite":"118 F.3d at 106"},{"src":"brief","b":1,"text":"needlessly paraded about a courtroom, like a dancing bear on a lead.","cite":"118 F.3d at 106"},{"src":"argument","who":"Mr. Kedem","text":"-- the government didn't in Zuber or LaFond, which were the Second and Eleventh Circuit decisions that were from final judgments, didn't contend there that it was improper for the litigant to argue that they had been improperly restrained in those cases."}]},{"t":"case","label":"Weinstein v. Bradford","cite":"423 U.S. 147","y":1975,"id":"1975/74-1287","sc":1,"by":{"0":"43"}},{"t":"case","label":"Will v. United States","cite":"389 U.S. 90","y":1967,"id":"1967/36","sc":1,"by":{"0":"12, 29, 30","1":"42, 43, 44","2":"11, 13, 14, 15"},"q":[{"src":"brief","b":0,"text":"a district court has engaged in ‘willful disobedience.’","cite":"389 U.S. 90, 100"},{"src":"brief","b":0,"text":"Mandamus, it must be remembered, does not run the gauntlet of reversible errors.","cite":"389 U.S. 90, 104"},{"src":"brief","b":1,"text":"‘the most that can be claimed on this record is that [the district court] may have erred in ruling on matters within [its] jurisdiction,’","cite":"389 U.S. 90, 103-04"},{"src":"brief","b":2,"text":"[T]his Court has never approved the use of the writ to review an interlocutory procedural order in a criminal case which did not have the effect of a dismissal.","cite":"389 U.S. 90, 98"},{"src":"brief","b":2,"text":"does not run the gauntlet of reversible errors.","cite":"389 U.S. at 104"}]},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"0":"34"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"35"}},{"t":"usc","label":"28 U.S.C. § 1651","url":"https://www.law.cornell.edu/uscode/text/28/1651","subs":["(a)"],"stext":{"head":"§1651. Writs","paras":[[0,"(a) The Supreme Court and all courts established by Act of Congress may issue all writs necessary or appropriate in aid of their respective jurisdictions and agreeable to the usages and principles of law."],[0,"(b) An alternative writ or rule nisi may be issued by a justice or judge of a court which has jurisdiction."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1651?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 10, 14, 27","1":"39","2":"11"},"q":[{"src":"brief","b":1,"text":"issue all writs necessary or appropriate in aid of their respective jurisdictions and agreeable to the usages and principles of law.","cite":"28 U.S.C. § 1651(a)"}]},{"t":"usc","label":"8 U.S.C. § 1325","url":"https://www.law.cornell.edu/uscode/text/8/1325","by":{"0":"8"}},{"t":"usc","label":"18 U.S.C. § 875","url":"https://www.law.cornell.edu/uscode/text/18/875","subs":["(c)"],"by":{"0":"8"}},{"t":"usc","label":"18 U.S.C. § 1544","url":"https://www.law.cornell.edu/uscode/text/18/1544","by":{"0":"8"}},{"t":"usc","label":"18 U.S.C. § 3145","url":"https://www.law.cornell.edu/uscode/text/18/3145","subs":["(c)"],"by":{"0":"18"}},{"t":"usc","label":"18 U.S.C. § 3731","url":"https://www.law.cornell.edu/uscode/text/18/3731","by":{"0":"18"}},{"t":"usc","label":"18 U.S.C. § 3742","url":"https://www.law.cornell.edu/uscode/text/18/3742","by":{"0":"18"}},{"t":"usc","label":"21 U.S.C. § 952","url":"https://www.law.cornell.edu/uscode/text/21/952","by":{"0":"8"}},{"t":"usc","label":"21 U.S.C. § 960","url":"https://www.law.cornell.edu/uscode/text/21/960","by":{"0":"8"}},{"t":"usc","label":"28 U.S.C. § 566","url":"https://www.law.cornell.edu/uscode/text/28/566","subs":["(a)","(i)"],"stext":{"head":"§566. Powers and duties","paras":[[0,"(a) It is the primary role and mission of the United States Marshals Service to provide for the security and to obey, execute, and enforce all orders of the United States District Courts, the United States Courts of Appeals, the Court of International Trade, and the United States Tax Court, as provided by law."],[0,"(b) The United States marshal of each district is the marshal of the district court and of the court of appeals when sitting in that district, and of the Court of International Trade holding sessions in that district, and may, in the discretion of the respective courts, be required to attend any session of court."],[0,"(c) Except as otherwise provided by law or Rule of Procedure, the United States Marshals Service shall execute all lawful writs, process, and orders issued under the authority of the United States, and shall command all necessary assistance to execute its duties."],[0,"(d) Each United States marshal, deputy marshal, and any other official of the Service as may be designated by the Director may carry firearms and make arrests without warrant for any offense against the United States committed in his or her presence, or for any felony cognizable under the laws of the United States if he or she has reasonable grounds to believe that the person to be arrested has committed or is committing such felony."],[0,"(e)(1) The United States Marshals Service is authorized to—"],[1,"(A) provide for the personal protection of Federal jurists, court officers, witnesses, and other threatened persons in the interests of justice where criminal intimidation impedes on the functioning of the judicial process or any other official proceeding;"],[1,"(B) investigate such fugitive matters, both within and outside the United States, as directed by the Attorney General;"],[1,"(C) issue administrative subpoenas in accordance with section 3486 of title 18, solely for the purpose of investigating unregistered sex offenders (as defined in such section 3486); and"],[1,"(D) assist State, local, and other Federal law enforcement agencies, upon the request of such an agency, in locating and recovering missing children."],[0,"(2) Nothing in paragraph (1)(B) shall be construed to interfere with or supersede the authority of other Federal agencies or bureaus."],[0,"(f) In accordance with procedures established by the Director, and except for public money deposited under section 2041 of this title, each United States marshal shall deposit public moneys that the marshal collects into the Treasury, subject to disbursement by the marshal. At the end of each accounting period, the earned part of public moneys accruing to the United States shall be deposited in the Treasury to the credit of the appropriate receipt accounts."],[0,"(g) Prior to resignation, retirement, or removal from office—"],[1,"(1) a United States marshal shall deliver to the marshal's successor all prisoners in his custody and all unserved process; and"],[1,"(2) a deputy marshal shall deliver to the marshal all process in the custody of the deputy marshal."],[0,"(h) The United States marshals shall pay such office expenses of United States Attorneys as may be directed by the Attorney General."],[0,"(i) The Director of the United States Marshals Service shall consult with the Judicial Conference of the United States on a continuing basis regarding the security requirements for the judicial branch of the United States Government, to ensure that the views of the Judicial Conference regarding the security requirements for the judicial branch of the Federal Government are taken into account when determining staffing levels, setting priorities for programs regarding judicial security, and allocating judicial security resources. In this paragraph, the term \"judicial security\" includes the security of buildings housing the judiciary, the personal security of judicial officers, the assessment of threats made to judicial officers, and the protection of all other judicial personnel. The United States Marshals Service retains final authority regarding security requirements for the judicial branch of the Federal Government."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/566?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 2"},"q":[{"src":"brief","b":0,"text":"retains final authority regarding security requirements for the judicial branch of the Federal Government.","cite":"28 U.S.C. 566(i)"}]},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","stext":{"head":"§1291. Final decisions of district courts","paras":[[0,"The courts of appeals (other than the United States Court of Appeals for the Federal Circuit) shall have jurisdiction of appeals from all final decisions of the district courts of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, and the District Court of the Virgin Islands, except where a direct review may be had in the Supreme Court. The jurisdiction of the United States Court of Appeals for the Federal Circuit shall be limited to the jurisdiction described in sections 1292(c) and (d) and 1295 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1291?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 13, 14, 16, 17, 20","1":"19","2":"3"},"q":[{"src":"brief","b":1,"text":"jurisdiction of appeals from all final decisions of the district courts of the United States.","cite":"28 U.S.C. § 1291"},{"src":"argument","who":"Mr. Kedem","text":"Appellate review was not authorized under Section 1291, which applies only to district court decisions that are final, nor under the All Writs Act."}]},{"t":"rule","label":"Fed. R. Crim. P. 16","url":"https://www.law.cornell.edu/rules/frcrmp/rule_16","by":{"0":"24"}},{"t":"case","label":"Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"by":{"1":"19, 20"},"q":[{"src":"brief","b":1,"text":"prevent review of all prejudgment orders.","cite":"556 U.S. 662, 671"}]},{"t":"case","label":"Atl. Marine Constr. Co. v. U.S. Dist. Court","cite":"134 S. Ct. 568","y":2013,"url":"https://www.courtlistener.com/c/S.%20Ct./134/568/","sc":1,"by":{"1":"47, 48"}},{"t":"case","label":"Burlington N.R.R. Co. v. Bhd. of Maint. of Way Emps.","cite":"481 U.S. 429","y":1987,"id":"1986/86-39","sc":1,"by":{"1":"55"}},{"t":"case","label":"Colgrove v. Battin","cite":"413 U.S. 149","y":1973,"id":"1972/71-1442","sc":1,"by":{"1":"48"}},{"t":"case","label":"Dig. Equip. Corp. v. Desktop Direct","cite":"511 U.S. 863","y":1994,"id":"1993/93-405","sc":1,"by":{"1":"19, 33"},"q":[{"src":"brief","b":1,"text":"not only from a district court decision that ends the litigation . . . but also from a narrow class of decisions that do not terminate the litigation, but must, in the interest of achieving a healthy legal system, nonetheless be treated as ‘final.’","cite":"511 U.S. 863, 867"},{"src":"brief","b":1,"text":"the entire category to which a claim belongs,","cite":"511 U.S. at 868"}]},{"t":"case","label":"Foley v. Blair & Co.","cite":"414 U.S. 212","y":1973,"id":"1973/72-1154","sc":1,"by":{"1":"52"}},{"t":"case","label":"Golden v. Zwickler","cite":"394 U.S. 103","y":1969,"id":"1968/370","sc":1,"by":{"1":"56"},"q":[{"src":"brief","b":1,"text":"is immediately in danger of sustaining some direct injury.","cite":"394 U.S. 103, 109–10"}]},{"t":"case","label":"Greenholtz v. Neb. Penal Inmates","cite":"442 U.S. 1","y":1979,"id":"1978/78-201","sc":1,"by":{"1":"26"}},{"t":"case","label":"Hamdi v. Rumsfeld","cite":"542 U.S. 507","y":2004,"id":"2003/03-6696","sc":1,"by":{"1":"27"},"q":[{"src":"brief","b":1,"text":"The gist of the Due Process Clause, as understood at the founding and since, was to force the Government to follow those common-law procedures traditionally deemed necessary before depriving a person of life, liberty, or property.","cite":"542 U.S. 507, 556"}]},{"t":"case","label":"Hollingsworth v. Perry","cite":"558 U.S. 183","y":2010,"id":"scdb/2009-018","sc":1,"by":{"1":"40, 45"},"q":[{"src":"brief","b":1,"text":"(1) ‘no other adequate means [exist] to attain the relief he desires,’ (2) the party’s ‘right to issuance of the writ is clear and indisputable,’ and (3) ‘the writ is appropriate under the circumstances.’","cite":"558 U.S. 183, 190"}]},{"t":"case","label":"Kerr v. U.S. Dist. Court for N. Dist.","cite":"426 U.S. 394","y":1976,"id":"1975/74-1023","sc":1,"by":{"1":"39, 42, 43"},"q":[{"src":"brief","b":1,"text":"has traditionally been used in the federal courts only to confine an inferior court to a lawful exercise of its prescribed jurisdiction or to compel it to exercise its authority when it is its duty to do so.","cite":"426 U.S. 394, 402"},{"src":"brief","b":1,"text":"not limited the use of mandamus by an unduly narrow and technical understanding of what constitutes a matter of ‘jurisdiction.’","cite":"426 U.S. at 402"}]},{"t":"case","label":"La. Buy v. Howes Leather, Co.","cite":"352 U.S. 249","y":1957,"id":"1956/27","sc":1,"by":{"1":"11, 39"},"q":[{"src":"brief","b":1,"text":"discretionary power to issue writs of mandamus in . . . exceptional circumstances.","cite":"352 U.S. at 255, 260"}]},{"t":"case","label":"Lambrix v. Singletary","cite":"520 U.S. 518","y":1997,"id":"1996/96-5658","sc":1,"by":{"1":"55"}},{"t":"case","label":"Mallard v. U.S. Dist. Court for S. Dist.","cite":"490 U.S. 296","y":1989,"id":"1988/87-1490","sc":1,"by":{"1":"42, 44, 48","2":"12, 14"},"q":[{"src":"argument","who":"Mr. Cahn","text":"But another species of mandamus is that that the Court authorized in Schlangenhauf and in Mallard and, indeed, I'd say even in Cheney, where there's a fundamental unresolved question about the authority of the district court."}]},{"t":"case","label":"MCI Telecomms. Corp. v. Credit Builders of Am., Inc.","cite":"508 U.S. 957","y":1993,"url":"https://supreme.justia.com/cases/federal/us/508/957/","sc":1,"by":{"1":"52"}},{"t":"case","label":"Mitchell v. Forsyth","cite":"472 U.S. 511","y":1985,"id":"1984/84-335","sc":1,"by":{"1":"22, 39"},"q":[{"src":"brief","b":1,"text":"unless it can be reviewed before [the proceedings terminate], it can never be reviewed at all.","cite":"472 U.S. 511, 525"}]},{"t":"case","label":"Neb. Press Ass’n v. Stuart","cite":"427 U.S. 539","y":1976,"id":"1975/75-817","sc":1,"by":{"1":"55"},"q":[{"src":"brief","b":1,"text":"prior restraint on publication [is] one of the most extraordinary remedies known to our jurisprudence,","cite":"427 U.S. at 562"}]},{"t":"case","label":"Platt v. Minnesota Min. & Mfg. Co.","cite":"376 U.S. 240","y":1964,"id":"1963/113","sc":1,"by":{"1":"43"}},{"t":"case","label":"Schlagenhauf v. Holder","cite":"379 U.S. 104","y":1964,"id":"1964/8","sc":1,"by":{"1":"33, 39, 44, 46, 47, 48","2":"15, 16"},"q":[{"src":"brief","b":1,"text":"when there is ‘usurpation of judicial power’ or a clear abuse of discretion.","cite":"379 U.S. at 110"},{"src":"argument","who":"Mr. Kedem","text":"Furthermore, my friend brought up the idea -- brought up the Schlagenhauf case. In Schlagenhauf, the argument was that a type of order that had never been issued before, an order requiring the criminal defendant to undergo a battery of psychological and mental examinations, that -"}]},{"t":"case","label":"Snyder v. Massachusetts","cite":"291 U.S. 97","y":1934,"id":"scdb/1933-072","sc":1,"by":{"1":"26"},"q":[{"src":"brief","b":1,"text":"so rooted in the traditions and conscience of our people as to be ranked as fundamental,","cite":"291 U.S. 97, 105"}]},{"t":"case","label":"United States v. Allied Oil Corp.","cite":"341 U.S. 1","y":1951,"id":"scdb/1950-054","sc":1,"by":{"1":"22"}},{"t":"case","label":"United States v. Boigegrain","cite":"122 F.3d 1345","y":1997,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/122/1345/","by":{"1":"24"}},{"t":"case","label":"United States v. Davis","cite":"93 F.3d 1286","y":1996,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/93/1286/","by":{"1":"24"}},{"t":"case","label":"United States v. Ferro","cite":"321 F.3d 756","y":2003,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/321/756/","by":{"1":"24"}},{"t":"case","label":"United States v. Filippi","cite":"211 F.3d 649","y":2000,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/211/649/","by":{"1":"24"}},{"t":"case","label":"United States v. Friedman","cite":"366 F.3d 975","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/366/975/","by":{"1":"24"}},{"t":"case","label":"United States v. Gold","cite":"790 F.2d 235","y":1986,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/790/235/","by":{"1":"24"}},{"t":"case","label":"United States v. Jicarilla Apache Nation","cite":"564 U.S. 162","y":2011,"id":"2010/10-382","sc":1,"by":{"1":"47"}},{"t":"case","label":"United States v. Weissberger","cite":"951 F.2d 392","y":1991,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/951/392/","by":{"1":"24"}},{"t":"case","label":"Wash. v. Glucksberg","cite":"521 U.S. 702","y":1997,"id":"1996/96-110","sc":1,"by":{"1":"26, 27"},"q":[{"src":"brief","b":1,"text":"deeply rooted in this Nation’s history and tradition,","cite":"521 U.S. 702, 720-21"},{"src":"brief","b":1,"text":"deeply rooted in this Nation’s history and tradition.","cite":"521 U.S. at 7202"}]},{"t":"case","label":"Will v. Calvert Fire Ins. Co.","cite":"437 U.S. 655","y":1978,"id":"1977/77-693","sc":1,"by":{"1":"45"}},{"t":"case","label":"Will v. Hallock","cite":"546 U.S. 345","y":2006,"id":"2005/04-1332","sc":1,"by":{"1":"21, 25, 35"},"q":[{"src":"brief","b":1,"text":"vindicating . . . a right to avoid trial,","cite":"546 U.S. at 350"},{"src":"brief","b":1,"text":"value of the interests that would be lost through rigorous application of a final judgment requirement,","cite":"546 U.S. at 3515"}]},{"t":"case","label":"Youngberg v. Romeo","cite":"457 U.S. 307","y":1982,"id":"1981/80-1429","sc":1,"by":{"1":"12, 26"},"q":[{"src":"brief","b":1,"text":"‘[l]iberty from bodily restraint always has been recognized as the core of the liberty protected by the Due Process Clause.’","cite":"457 U.S. 307, 316"},{"src":"brief","b":1,"text":"[l]iberty from bodily restraint always has been recognized as the core of the liberty protected by the Due Process Clause from arbitrary governmental action.","cite":"457 U.S. 307, 316"},{"src":"argument","who":"Mr. Cahn","text":"They talk about Youngberg versus Romeo and that this is a deprivation of the fundamental right to be free of restraints. Now we've talked about Deck because Deck talks about what goes on in the courtroom."}]},{"t":"usc","label":"18 U.S.C. § 4241","url":"https://www.law.cornell.edu/uscode/text/18/4241","by":{"1":"24"}},{"t":"usc","label":"28 U.S.C. § 1292","url":"https://www.law.cornell.edu/uscode/text/28/1292","by":{"1":"33, 34"}},{"t":"usc","label":"28 U.S.C. § 1404","url":"https://www.law.cornell.edu/uscode/text/28/1404","by":{"1":"47, 48"}},{"t":"usc","label":"28 U.S.C. § 1915","url":"https://www.law.cornell.edu/uscode/text/28/1915","subs":["(d)"],"stext":{"head":"§1915. Proceedings in forma pauperis","paras":[[0,"(a)(1) Subject to subsection (b), any court of the United States may authorize the commencement, prosecution or defense of any suit, action or proceeding, civil or criminal, or appeal therein, without prepayment of fees or security therefor, by a person who submits an affidavit that includes a statement of all assets such prisoner possesses that the person is unable to pay such fees or give security therefor. Such affidavit shall state the nature of the action, defense or appeal and affiant's belief that the person is entitled to redress."],[0,"(2) A prisoner seeking to bring a civil action or appeal a judgment in a civil action or proceeding without prepayment of fees or security therefor, in addition to filing the affidavit filed under paragraph (1), shall submit a certified copy of the trust fund account statement (or institutional equivalent) for the prisoner for the 6-month period immediately preceding the filing of the complaint or notice of appeal, obtained from the appropriate official of each prison at which the prisoner is or was confined."],[0,"(3) An appeal may not be taken in forma pauperis if the trial court certifies in writing that it is not taken in good faith."],[0,"(b)(1) Notwithstanding subsection (a), if a prisoner brings a civil action or files an appeal in forma pauperis, the prisoner shall be required to pay the full amount of a filing fee. The court shall assess and, when funds exist, collect, as a partial payment of any court fees required by law, an initial partial filing fee of 20 percent of the greater of—"],[1,"(A) the average monthly deposits to the prisoner's account; or"],[1,"(B) the average monthly balance in the prisoner's account for the 6-month period immediately preceding the filing of the complaint or notice of appeal."],[0,"(2) After payment of the initial partial filing fee, the prisoner shall be required to make monthly payments of 20 percent of the preceding month's income credited to the prisoner's account. The agency having custody of the prisoner shall forward payments from the prisoner's account to the clerk of the court each time the amount in the account exceeds $10 until the filing fees are paid."],[0,"(3) In no event shall the filing fee collected exceed the amount of fees permitted by statute for the commencement of a civil action or an appeal of a civil action or criminal judgment."],[0,"(4) In no event shall a prisoner be prohibited from bringing a civil action or appealing a civil or criminal judgment for the reason that the prisoner has no assets and no means by which to pay the initial partial filing fee."],[0,"(c) Upon the filing of an affidavit in accordance with subsections (a) and (b) and the prepayment of any partial filing fee as may be required under subsection (b), the court may direct payment by the United States of the expenses of (1) printing the record on appeal in any civil or criminal case, if such printing is required by the appellate court; (2) preparing a transcript of proceedings before a United States magistrate judge in any civil or criminal case, if such transcript is required by the district court, in the case of proceedings conducted under section 636(b) of this title or under section 3401(b) of title 18, United States Code; and (3) printing the record on appeal if such printing is required by the appellate court, in the case of proceedings conducted pursuant to section 636(c) of this title. Such expenses shall be paid when authorized by the Director of the Administrative Office of the United States Courts."],[0,"(d) The officers of the court shall issue and serve all process, and perform all duties in such cases. Witnesses shall attend as in other cases, and the same remedies shall be available as are provided for by law in other cases."],[0,"(e)(1) The court may request an attorney to represent any person unable to afford counsel."],[0,"(2) Notwithstanding any filing fee, or any portion thereof, that may have been paid, the court shall dismiss the case at any time if the court determines that—"],[1,"(A) the allegation of poverty is untrue; or"],[1,"(B) the action or appeal—"],[2,"(i) is frivolous or malicious;"],[2,"(ii) fails to state a claim on which relief may be granted; or"],[2,"(iii) seeks monetary relief against a defendant who is immune from such relief."],[0,"(f)(1) Judgment may be rendered for costs at the conclusion of the suit or action as in other proceedings, but the United States shall not be liable for any of the costs thus incurred. If the United States has paid the cost of a stenographic transcript or printed record for the prevailing party, the same shall be taxed in favor of the United States."],[0,"(2)(A) If the judgment against a prisoner includes the payment of costs under this subsection, the prisoner shall be required to pay the full amount of the costs ordered."],[0,"(B) The prisoner shall be required to make payments for costs under this subsection in the same manner as is provided for filing fees under subsection (a)(2)."],[0,"(C) In no event shall the costs collected exceed the amount of the costs ordered by the court."],[0,"(g) In no event shall a prisoner bring a civil action or appeal a judgment in a civil action or proceeding under this section if the prisoner has, on 3 or more prior occasions, while incarcerated or detained in any facility, brought an action or appeal in a court of the United States that was dismissed on the grounds that it is frivolous, malicious, or fails to state a claim upon which relief may be granted, unless the prisoner is under imminent danger of serious physical injury."],[0,"(h) As used in this section, the term \"prisoner\" means any person incarcerated or detained in any facility who is accused of, convicted of, sentenced for, or adjudicated delinquent for, violations of criminal law or the terms and conditions of parole, probation, pretrial release, or diversionary program."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1915?type=usc&year=mostrecent&link-type=html"},"by":{"1":"44, 48","2":"14"}},{"t":"rule","label":"Fed. R. Civ. P. 35","url":"https://www.law.cornell.edu/rules/frcp/rule_35","by":{"1":"46, 47, 48"}},{"t":"case","label":"Bankers Life & Cas. Co. v. Holland","cite":"346 U.S. 379","y":1953,"id":"scdb/1953-011","sc":1,"by":{"2":"14"}},{"t":"case","label":"Coleman v. Tollefson","cite":"135 S. Ct. 1759","y":2015,"id":"2014/13-1333","sc":1,"by":{"2":"14"}},{"t":"case","label":"DiBella v. United States","cite":"369 U.S. 121","y":1962,"id":"1961/21","sc":1,"by":{"2":"6"},"q":[{"src":"brief","b":2,"text":"are especially inimical to the effective and fair administration of the criminal law.","cite":"369 U.S. 121, 126"}]},{"t":"case","label":"McKaskle v. Wiggins","cite":"465 U.S. 168","y":1984,"id":"1983/82-1135","sc":1,"by":{"2":"5"},"q":[{"src":"brief","b":2,"text":"to affirm the dignity and autonomy of the accused,","cite":"465 U.S. 168, 176-177"}]},{"t":"case","label":"Rodriguez de Quijas v. Shearson/American Express, Inc.","cite":"490 U.S. 477","y":1989,"id":"1988/88-385","sc":1,"by":{"2":"13"}},{"t":"case","label":"United States v. Munsingwer, Inc.","cite":"340 U.S. 36","y":1950,"id":"scdb/1950-004","sc":1,"by":{"2":"18"}},{"t":"case","label":"Weaver v. Massachusetts","cite":"137 S. Ct. 1899","y":2017,"id":"2016/16-240","sc":1,"by":{"2":"6"}}]};